def raison_non_desinstallable(fiche: dict[str, Any]) -> str:
    """Pourquoi Vision refuse de désinstaller ceci — chaîne vide s'il veut bien."""
    if protege(fiche):
        return "fait partie de Windows ou de sa protection"
    exe = (fiche.get("exe") or "").strip().lower()
    chemin = (fiche.get("chemin") or "").strip().lower().replace("/", "\\")
    qui = " ".join(
        str(fiche.get(c) or "") for c in ("signataire", "editeur")
    ).strip().lower() + " "
    if exe in ANTITRICHE or "anticheat" in chemin or "anti-cheat" in chemin or "vanguard" in chemin:
        return "est l'anti-triche d'un jeu"
    if "\\haparental" in chemin or "\\vision\\" in chemin and "agent" in chemin:
        return "est l'agent Vision"
    if qui.strip().startswith("microsoft"):
        return "est un logiciel Microsoft"
    if "\\drivers\\" in chemin or "\\driverstore\\" in chemin:
        return "est un pilote"
    if any(e in qui for e in EDITEURS_PILOTES):
        return "vient d'un fabricant de composants (pilote probable)"
    if not chemin:
        return "n'a pas d'emplacement connu"
    return ""


